/* Drawing controls use the board's existing history, camera and autosave. */
let drawMode=null,drawColor='#64764c',drawWidth=6,drawGlow=12;
const drawButton=document.createElement('button');drawButton.id='addDrawing';drawButton.innerHTML='✎ <span>그리기</span>';drawButton.setAttribute('aria-pressed','false');$('addSticker').after(drawButton);
const inkPreview=document.createElement('canvas');inkPreview.id='inkPreview';inkPreview.setAttribute('aria-hidden','true');$('stage').append(inkPreview);
const drawPanel=document.createElement('aside');drawPanel.id='drawingPanel';drawPanel.hidden=true;drawPanel.setAttribute('aria-label','그리기 도구');drawPanel.innerHTML='<div class="drawing-title"><b>그리기</b><button id="closeDrawing" aria-label="그리기 모드 종료">완료</button></div><div class="drawing-tools"><button data-pen="pen" class="active">일반 펜</button><button data-pen="neon">네온 펜</button><button data-pen="eraser">지우개</button></div><label id="drawColorLabel">색상<button id="drawColor">색 선택</button></label><label><span id="drawWidthLabel">굵기 · 6</span><input id="drawWidth" aria-label="펜 또는 지우개 굵기" type="range" min="1" max="40" value="6"></label><label id="drawGlowLabel"><span id="drawGlowValue">발광 · 12</span><input id="drawGlow" aria-label="네온 발광 강도" type="range" min="0" max="24" value="12"></label><div class="drawing-history"><button id="drawUndo">실행 취소</button><button id="drawRedo">다시 실행</button></div><small>한 손가락으로 그리기 · 두 손가락으로 이동·확대</small>';$('stage').append(drawPanel);
function setDrawing(value){if(gesture?.kind==='ink'||gesture?.kind==='erase')finishDrawing();drawMode=value;drawPanel.hidden=!value;drawButton.setAttribute('aria-pressed',String(!!value));document.body.classList.toggle('drawing-active',!!value);if(value){selection=null;tool=null;updateInspector()}document.querySelectorAll('[data-pen]').forEach(b=>b.classList.toggle('active',b.dataset.pen===value));$('drawColorLabel').hidden=value==='eraser';$('drawGlowLabel').hidden=value!=='neon';$('drawWidth').max=value==='eraser'?160:40;if(value!=='eraser'&&drawWidth>40)drawWidth=40;$('drawWidth').value=drawWidth;$('drawWidthLabel').textContent=(value==='eraser'?'지우개 크기':'굵기')+' · '+drawWidth;$('hint').textContent=value?(value==='eraser'?'지우개 사용 중 · 그림만 지워요 · 두 손가락으로 이동':'그리기 중 · 한 손가락은 펜 · 두 손가락은 카메라'):defaultHint();render()}
drawButton.onclick=()=>setDrawing(drawMode?null:'pen');$('closeDrawing').onclick=()=>setDrawing(null);document.querySelectorAll('[data-pen]').forEach(b=>b.onclick=()=>setDrawing(b.dataset.pen));$('drawColor').onclick=()=>chooseColor(drawColor,c=>{drawColor=c;paintColor($('drawColor'),c)});paintColor($('drawColor'),drawColor);$('drawWidth').oninput=e=>{drawWidth=Number(e.target.value);$('drawWidthLabel').textContent=(drawMode==='eraser'?'지우개 크기':'굵기')+' · '+drawWidth};$('drawGlow').oninput=e=>{drawGlow=Number(e.target.value);$('drawGlowValue').textContent='발광 · '+drawGlow};$('drawUndo').onclick=undo;$('drawRedo').onclick=redo;
function startDrawing(p){selection=null;updateInspector();if(drawMode==='eraser'){gesture={kind:'erase',last:p,mutated:false};eraseDrawing(p)}else gesture={kind:'ink',points:[p],settings:{kind:drawMode,color:drawColor,width:drawWidth,glow:drawMode==='neon'?drawGlow:0}};render()}
function eraseDrawing(p){let result=MuseDrawing.erase(state.items,gesture.last,p,drawWidth/2,()=>crypto.randomUUID());gesture.last=p;if(!result.changed)return;if(result.items.length>1000||result.items.reduce((n,o)=>n+(o.drawing?.points.length||0),0)>30000){toast('전시품이 많아요. 일부 그림을 정리한 뒤 다시 지워주세요.');return}if(!gesture.mutated){beginChange();gesture.mutated=true}state.items=result.items;render()}
function moveDrawing(e){let p=world(e);p.x=E.clamp(p.x,0,E.W);p.y=E.clamp(p.y,0,E.H);if(gesture.kind==='erase'){eraseDrawing(p);return}let last=gesture.points.at(-1);if(Math.hypot(last.x-p.x,last.y-p.y)<1.5/cam.z)return;if(gesture.points.length>=512){if(!gesture.truncated){gesture.truncated=true;toast('긴 획은 여기까지 기록해요. 손을 떼고 이어서 그려주세요.')}return}gesture.points.push(p);drawInkPreview()}
function finishDrawing(cancel=false){if(!gesture)return;if(gesture.kind==='ink'){if(!cancel){if(state.items.length>=1000||state.items.reduce((n,o)=>n+(o.drawing?.points.length||0),0)+gesture.points.length>30000)toast('전시품이 많아요. 일부 요소를 정리해주세요.');else{let o=MuseDrawing.stroke(gesture.points,gesture.settings,crypto.randomUUID(),nextZ());beginChange();state.items.push(o);changed()}}}else if(gesture.kind==='erase'&&gesture.mutated)changed();gesture=null;drawInkPreview();render()}
function previewDrawing(c){if(gesture?.kind!=='ink')return;let o=MuseDrawing.stroke(gesture.points,gesture.settings,'preview',0);c.save();c.translate(o.x,o.y);MuseDrawing.draw(c,o);c.restore()}
function drawInkPreview(){let dpr=Math.min(devicePixelRatio||1,2);if(inkPreview.width!==Math.round(viewport.w*dpr)||inkPreview.height!==Math.round(viewport.h*dpr)){inkPreview.width=Math.round(viewport.w*dpr);inkPreview.height=Math.round(viewport.h*dpr)}let c=inkPreview.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,viewport.w,viewport.h);if(mode!=='edit'||gesture?.kind!=='ink')return;c.translate(viewport.w/2,viewport.h/2);c.scale(cam.z,cam.z);c.translate(-cam.x,-cam.y);previewDrawing(c)}
window.MuseDrawingUI={exit:()=>setDrawing(null),preview:drawInkPreview};
